// Smoke del percorso reale shell → sessione → superficie in Chromium.
// Il fake non valuta formule: verifica il fallback, non duplica Rust.
import assert from "node:assert/strict";
import { mkdir, writeFile } from "node:fs/promises";
import { join } from "node:path";
import { createRequire } from "node:module";
import { openStage, openPage, OUTPUT } from "./stage.mjs";

const require = createRequire(import.meta.url);
const DOC = "Banco.fubsheet";
const source = JSON.stringify({ version: 1, sheets: [{
  id: "main", name: "Banco",
  rows: Array.from({ length: 120 }, (_, i) => ({ id: `r${i}`, hidden: false })),
  columns: Array.from({ length: 60 }, (_, i) => ({ id: `c${i}`, hidden: false })),
  cells: [{ row: "r0", column: "c0", input: "1" },
    { row: "r0", column: "c1", input: "=A1+1" }],
}] });
const stage = await openStage();
const report = [];
try {
  for (const light of ["dark", "light"]) {
    const page = await openPage(stage.browser, light);
    const errors = [];
    page.on("pageerror", (e) => errors.push(e.message));
    try {
      await page.goto(`${stage.base}/?light=${light}`);
      await page.waitForSelector('html[data-bench="ready"]');
      await page.evaluate(async ({ doc, source }) => {
        const { api } = await import("/bench/fake-ipc.ts");
        await api.writeDocument(doc, source, { kind: "dictated" });
        const { openDocument } = await import("/src/panels/document.ts");
        await openDocument(doc);
      }, { doc: DOC, source });
      const viewport = page.locator(".grid-viewport").first();
      await viewport.waitFor({ state: "visible" });
      const cells = await page.locator(".grid-cell").count();
      assert(cells > 0 && cells < 1000, `virtualizzazione: ${cells}/7200`);
      assert.equal(await viewport.getAttribute("role"), "grid");
      await page.addScriptTag({ path: require.resolve("axe-core/axe.min.js") });
      const a11y = await page.evaluate(async () => window.axe.run(".grid-surface", {
        runOnly: { type: "rule", values: ["color-contrast", "aria-allowed-attr", "aria-valid-attr-value", "aria-required-parent", "aria-required-children"] },
      }));
      assert.deepEqual(a11y.violations.map((v) => ({ id: v.id, nodes: v.nodes.map((n) => n.target) })), [], "accessibilità grid");
      await page.waitForFunction(() => document.querySelector('.grid-cell[data-row="0"][data-column="1"]')?.textContent === "=A1+1");
      const calls = () => page.evaluate(() => window.bench.calls.filter((c) => c.gate === "callService").length);
      const input = (row = "r0", column = "c0") => page.evaluate(async ({ doc, row, column }) => {
        const { documentSessions } = await import("/src/state/document-session.ts");
        const book = JSON.parse(documentSessions.text(doc));
        return book.sheets[0].cells.find((c) => c.row === row && c.column === column)?.input ?? "";
      }, { doc: DOC, row, column });
      const before = await calls();
      await viewport.focus();
      await page.keyboard.press("F2");
      const editor = page.locator(".grid-cell-editor .cm-content").first();
      await editor.fill("27");
      assert.equal(await input(), "1", "la bozza resta locale");
      assert.equal(await calls(), before, "nessuna valutazione per battuta");
      await editor.press("Escape");
      assert.equal(await input(), "1", "cancel non committa");
      await viewport.press("F2");
      await editor.fill("42");
      await editor.press("Enter");
      assert.equal(await input(), "42");
      assert.equal(await calls(), before + 1, "un commit, una valutazione");
      await viewport.press("Control+z");
      assert.equal(await input(), "1");
      await viewport.press("Control+Shift+z");
      assert.equal(await input(), "42");
      const formula = page.locator(".grid-formula-editor .cm-content").first();
      await formula.fill("99");
      await formula.press("Enter");
      assert.equal(await input(), "99", "formula bar usa il motore condiviso");
      await viewport.evaluate((el) => {
        const clipboard = new DataTransfer();
        clipboard.setData("text/plain", "A\tB\nC\tD");
        el.dispatchEvent(new ClipboardEvent("paste", { clipboardData: clipboard, bubbles: true, cancelable: true }));
      });
      assert.equal(await input("r1", "c1"), "D");
      await viewport.press("Control+z");
      assert.equal(await input(), "99", "incolla atomico nell'undo");
      assert.equal(await input("r1", "c1"), "");
      await viewport.evaluate((el) => { el.scrollTop = 2200; el.scrollLeft = 3600; });
      await page.waitForFunction(() => Number(document.querySelector(".grid-cell")?.dataset.row) > 40);
      assert((await page.locator(".grid-cell").count()) < 1000);
      await page.evaluate(async (doc) => {
        const { documentSessions } = await import("/src/state/document-session.ts");
        if (await documentSessions.flush(doc)) throw new Error("flush failed");
        const { closeDocument } = await import("/src/panels/document.ts");
        closeDocument(doc);
      }, DOC);
      await page.waitForFunction(() => document.querySelectorAll(".grid-viewport").length === 0);
      await page.evaluate(async (doc) => (await import("/src/panels/document.ts")).openDocument(doc), DOC);
      await viewport.waitFor({ state: "visible" });
      assert.equal(await input(), "99", "salvataggio e riapertura conservano input");
      assert.deepEqual(errors, [], "nessun errore browser non gestito");
      report.push({ light, cells, total: 7200, typingLocal: true, commitCancel: true,
        undoRedo: true, formulaBar: true, atomicPaste: true, virtualScroll: true,
        reopen: true, rawFormulaFallback: true, a11y: { violations: a11y.violations.length, incomplete: a11y.incomplete.map((v) => v.id) }, pageErrors: errors });
      console.log(`${light}: grid smoke OK (${cells}/7200 celle nel DOM)`);
    } finally { await page.close(); }
  }
} finally {
  await stage.close();
  await mkdir(OUTPUT, { recursive: true });
  await writeFile(join(OUTPUT, "grid.json"), JSON.stringify(report, null, 2));
}

it("collega celle e intestazioni a righe ARIA e non punta a celle fuori finestra", () => {
  const { engine, host, viewport } = mounted();
  try {
    for (const cell of host.querySelectorAll('[role="gridcell"], [role="rowheader"], [role="columnheader"]')) {
      expect(cell.parentElement?.getAttribute("role")).toBe("row");
    }
    const active = viewport.getAttribute("aria-activedescendant");
    expect(active).not.toBeNull();
    expect(document.getElementById(active!)).not.toBeNull();
    viewport.scrollTop = 1400;
    viewport.dispatchEvent(new Event("scroll"));
    expect(viewport.hasAttribute("aria-activedescendant")).toBe(false);
    expect(engine.selection().focus).toEqual({ row: 0, column: 0 });
  } finally { engine.destroy(); }
});

